from datetime import date, timedelta
from collections import defaultdict


class LeaveTracker:
    def __init__(self, days_per_year: int = 26, holidays: list[date] | None = None) -> None:
        self.days_per_year = days_per_year
        self.holidays = set(holidays) if holidays is not None else set()
        # Maps employee -> year -> used_days
        self.used_leave: dict[str, dict[int, int]] = defaultdict(lambda: defaultdict(int))

    def request(self, employee: str, start: date, end: date, today: date) -> int:
        """Request leave from start to end (inclusive); returns the number of leave days used."""
        if end < start:
            raise ValueError("End date cannot be before start date.")

        if (start - today).days < 3:
            raise ValueError("Leave request must be made at least 3 days in advance.")

        # Count leave days requested per year
        days_per_year_needed: dict[int, int] = defaultdict(int)
        curr = start
        one_day = timedelta(days=1)
        while curr <= end:
            # Weekday check: Monday is 0, Sunday is 6. Weekends are 5 and 6.
            if curr.weekday() < 5 and curr not in self.holidays:
                days_per_year_needed[curr.year] += 1
            curr += one_day

        # Check if the employee has enough remaining days for each year affected
        for year, needed in days_per_year_needed.items():
            if self.remaining(employee, year) < needed:
                raise ValueError(
                    f"Employee '{employee}' does not have enough remaining leave days for year {year}."
                )

        # Deduct the days
        total_days = 0
        for year, needed in days_per_year_needed.items():
            self.used_leave[employee][year] += needed
            total_days += needed

        return total_days

    def remaining(self, employee: str, year: int) -> int:
        return self.days_per_year - self.used_leave[employee][year]
